INSERT INTO public.words (id, word, meaning, detailed_meaning, news_example, hint, related_words, visuals, sources) VALUES
(1001,'암묵적 비용','어떤 선택을 하느라 포기한 수입처럼 장부에 찍히지 않는 비용','암묵적 비용은 실제로 돈이 나가지는 않지만 그 일을 하느라 포기한 연봉, 임대 수입, 예금 이자 같은 것이다. 명시적 비용과 더하면 경제학적 비용, 곧 기회비용이 된다. 창업이나 진학처럼 큰 선택을 따질 때 빠뜨리기 쉬운 비용이다.','','ㅇㅁㅈㅂㅇ',ARRAY['명시적 비용','기회비용','경제학적 이익','정상이윤']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "회사를 그만두고 가게를 열면 월급이 끊겨요.\n통장에서 돈이 나간 건 아니지만 포기한 월급도 비용이에요.\n이렇게 눈에 안 보이는 비용이 암묵적 비용이에요."}, {"type": "table", "title": "명시적 비용 vs 암묵적 비용", "columns": ["구분", "명시적 비용", "암묵적 비용"], "rows": [["뜻", "실제로 지출한 돈", "그 일을 하느라 포기한 것"], ["예시", "수강료, 재료비, 운영비", "받던 연봉, 임대 수입, 예금 이자"], ["합치면", "경제학적 비용(기회비용)", "경제학적 비용(기회비용)"]]}, {"type": "table", "title": "제과점 창업 예시", "columns": ["항목", "금액", "구분"], "rows": [["포기한 연봉", "2,000만원", "암묵적"], ["포기한 임대 수입", "1,000만원", "암묵적"], ["운영비", "1,500만원", "명시적"], ["기회비용 합계", "4,500만원", ""]], "caption": "예상 수입이 4,000만원이면 비용 합계보다 적어 여는 게 손해예요."}, {"type": "text", "title": "왜 중요할까?", "body": "예금은 원금이 아니라 포기한 이자만 비용으로 넣어요.\n포기한 수입을 빼먹으면 손해 보는 선택도 이득처럼 보여요."}]'::jsonb,ARRAY['tesat']::text[]),
(1002,'명시적 비용','임금, 재료비, 임대료처럼 실제로 돈을 내서 장부에 기록되는 비용','명시적 비용은 생산이나 선택을 위해 실제로 지출한 돈으로, 회계학적 비용이라고도 한다. 장부에 찍히는 돈만 보기 때문에 포기한 수입은 들어가지 않는다. 여기에 암묵적 비용을 더해야 경제학에서 말하는 기회비용이 된다.','','ㅁㅅㅈㅂㅇ',ARRAY['암묵적 비용','회계학적 이익','기회비용']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "고시 공부에 수강료와 교재값으로 1천만원을 썼다면\n이 1천만원이 명시적 비용이에요.\n영수증이 남는 돈이라고 생각하면 쉬워요."}, {"type": "table", "title": "고시 공부 예시", "columns": ["구분", "금액", "내용"], "rows": [["명시적 비용", "1천만원", "수강료·교재값"], ["암묵적 비용", "2천만원", "포기한 연봉"], ["경제학적 비용", "3천만원", "둘의 합"]], "caption": "1천만원만 들었다고 생각하기 쉽지만 실제로는 3천만원을 내려놓은 선택이에요."}]'::jsonb,ARRAY['tesat']::text[]),
(1003,'회계학적 이익','총수입에서 실제로 지출한 돈만 뺀 장부상의 이익','회계학적 이익은 총수입에서 명시적 비용만 빼서 구한다. 포기한 연봉이나 임대 수입 같은 암묵적 비용은 빼지 않기 때문에 경제학적 이익보다 항상 크거나 같다. 기업 재무제표에 나오는 이익은 대부분 이 기준이다.','','ㅎㄱㅎㅈㅇㅇ',ARRAY['경제학적 이익','명시적 비용','순이익']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "4,000만원 벌고 운영비 1,500만원을 쓰면\n장부에는 2,500만원이 남아요.\n이게 회계학적 이익이에요."}, {"type": "table", "title": "같은 가게, 두 가지 이익", "columns": ["기준", "수입 4,000만원", "수입 5,000만원"], "rows": [["회계학적 이익", "2,500만원", "3,500만원"], ["경제학적 이익", "-500만원", "500만원"], ["판단", "열지 않음", "여는 게 합리적"]], "caption": "포기한 연봉 2,000만원과 임대 수입 1,000만원까지 빼면 경제학적 이익이 나와요."}]'::jsonb,ARRAY['tesat']::text[]),
(1004,'경제학적 이익','총수입에서 명시적 비용과 암묵적 비용을 모두 뺀 이익','경제학적 이익은 총수입에서 기회비용 전체, 곧 명시적 비용과 암묵적 비용을 뺀 값이다. 이 값이 0보다 커야 다른 선택보다 나은 선택이라고 본다. 포기한 수입까지 빼므로 회계학적 이익보다 항상 작거나 같다.','','ㄱㅈㅎㅈㅇㅇ',ARRAY['회계학적 이익','암묵적 비용','초과이윤','기회비용']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "번 돈에서 쓴 돈만 빼면 회계학적 이익이에요.\n포기한 월급까지 빼야 경제학적 이익이에요.\n0보다 크면 그 선택이 다른 선택보다 나아요."}, {"type": "flow", "title": "경제학적 이익 구하는 순서", "steps": ["총수입 확인", "명시적 비용(낸 돈) 빼기", "암묵적 비용(포기한 수입) 빼기", "0보다 크면 선택"], "caption": "이미 써서 못 돌려받는 매몰비용은 계산에서 빼요."}, {"type": "text", "title": "왜 중요할까?", "body": "경제학적 이익이 0이라는 건 망했다는 뜻이 아니에요.\n다른 데서 벌 수 있던 만큼은 번 상태라는 뜻이에요."}]'::jsonb,ARRAY['tesat']::text[]),
(1005,'초과이윤','가게를 유지할 최소 몫인 정상이윤을 넘어서 더 벌어들이는 이윤','초과이윤은 가격에서 비용과 정상이윤을 빼고도 남는 몫으로, 경제적 이윤이라고도 한다. 독점처럼 경쟁이 없을 때 생기며, 경쟁이 붙으면 새 기업이 들어와 결국 0이 된다. 초과이윤이 사라져도 정상이윤은 남는다.','','ㅊㄱㅇㅇ',ARRAY['정상이윤','경제학적 이익','완전경쟁시장','독점']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "마을에 빵집이 하나뿐이면 빵을 10만원에 팔 수도 있어요.\n비용과 적정 마진을 넘는 이 바가지 몫이 초과이윤이에요.\n빵집이 늘면 서로 값을 내려 이 몫이 사라져요."}, {"type": "table", "title": "빵집 수와 빵 가격", "columns": ["빵집 수", "빵 가격", "상황"], "rows": [["1곳(독점)", "10만원", "초과이윤이 큼"], ["2곳", "1만원", "가격 경쟁 시작"], ["여러 곳", "2,000원", "초과이윤 0, 정상이윤만 남음"]]}, {"type": "text", "title": "왜 중요할까?", "body": "\"경쟁하면 초과이윤이 0이 된다\"는 맞는 말이에요.\n\"경쟁하면 정상이윤이 0이 된다\"는 틀린 말이에요."}]'::jsonb,ARRAY['tesat']::text[]),
(1006,'정상이윤','기업이 그 사업을 계속하도록 붙잡아 두는 데 필요한 최소한의 이윤','정상이윤은 기업가가 다른 곳에서 벌 수 있었던 몫으로, 경제학에서는 암묵적 비용으로 보고 비용에 넣는다. 그래서 경제적 이윤이 0이라는 말은 정상이윤만 남았다는 뜻이다. 완전경쟁에서도 정상이윤은 사라지지 않는다.','','ㅈㅅㅇㅇ',ARRAY['초과이윤','암묵적 비용','완전경쟁시장']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "2,000원짜리 빵의 비용이 1,500원이면 500원이 남아요.\n주인이 먹고살 만큼의 이 몫이 정상이윤이에요.\n경쟁이 치열해도 이 몫까지 사라지면 아무도 빵을 안 구워요."}, {"type": "table", "title": "정상이윤 vs 초과이윤", "columns": ["구분", "정상이윤", "초과이윤"], "rows": [["뜻", "사업을 계속할 최소 마진", "정상이윤을 넘는 몫"], ["경쟁 후", "남음", "0이 됨"], ["경제학의 분류", "비용(암묵적 비용)에 포함", "경제적 이윤"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1007,'경제주체','가계·기업·정부·외국처럼 경제 활동에 참여해 스스로 결정하는 단위','경제주체는 생산, 소비, 분배 같은 경제 활동을 하는 단위로 가계, 기업, 정부, 외국으로 나눈다. 가계는 효용, 기업은 이윤, 정부는 사회후생을 극대화하려 한다. 가계와 기업을 민간 부문, 정부를 공공 부문으로 묶는다.','','ㄱㅈㅈㅊ',ARRAY['생산물 시장','생산요소 시장','효용 극대화','사회후생']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "우리 집은 가계, 회사는 기업, 나라 살림은 정부예요.\n무역 상대인 다른 나라는 외국이에요.\n각자 원하는 게 달라서 시장에서 서로 거래해요."}, {"type": "table", "title": "경제주체와 목표", "columns": ["경제주체", "추구하는 것", "생산물 시장", "생산요소 시장"], "rows": [["가계", "효용 극대화", "소비자(수요)", "노동 공급자"], ["기업", "이윤 극대화", "판매자(공급)", "고용주(수요)"], ["정부", "사회후생 극대화", "공공재·서비스 공급", "-"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1008,'생산물 시장','기업이 만든 재화와 서비스가 가계에 팔리는 시장','생산물 시장은 재화와 서비스가 거래되는 시장으로, 기업이 공급자이고 가계가 수요자다. 생산요소 시장과는 가계와 기업의 역할이 서로 뒤바뀐다. 공급에는 물건뿐 아니라 서비스도 모두 들어간다.','','ㅅㅅㅁㅅㅈ',ARRAY['생산요소 시장','경제주체','수요와 공급']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "마트에서 우유를 사고 미용실에서 머리를 자르는 곳이에요.\n기업은 팔고 가계는 사요."}, {"type": "table", "title": "두 시장에서 역할 비교", "columns": ["구분", "생산물 시장", "생산요소 시장"], "rows": [["가계", "수요자(소비)", "공급자(노동 제공)"], ["기업", "공급자(판매)", "수요자(고용)"], ["거래 대상", "재화·서비스", "노동·자본·토지"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1009,'생산요소 시장','노동·자본·토지처럼 생산에 쓰이는 요소가 거래되는 시장','생산요소 시장은 기업이 생산에 필요한 노동, 자본, 토지를 사는 시장이다. 여기서는 가계가 공급자, 기업이 수요자가 되며 대표적인 예가 노동시장이다. 가계는 생산요소를 제공한 대가로 임금, 이자, 지대를 받는다.','','ㅅㅅㅇㅅㅅㅈ',ARRAY['생산요소','생산물 시장','경제주체']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "내가 회사에 노동을 팔고 월급을 받는 곳이에요.\n이때는 가계가 파는 쪽, 기업이 사는 쪽이에요."}, {"type": "flow", "title": "돈과 생산요소의 흐름", "steps": ["가계가 노동·자본·토지 제공", "기업이 생산에 사용", "가계가 임금·이자·지대 받음", "그 소득으로 생산물 시장에서 소비"]}]'::jsonb,ARRAY['tesat']::text[]),
(1010,'생산요소','노동·자본·토지처럼 재화와 서비스를 만드는 데 들어가는 것','생산요소는 생산에 투입되는 자원으로 대표적으로 노동, 자본, 토지가 있다. 각 생산요소를 제공한 대가로 노동은 임금, 자본은 이자, 토지는 지대를 받는다. 생산요소 가격이 오르면 생산비가 늘어 공급이 줄어든다.','','ㅅㅅㅇㅅ',ARRAY['생산요소 시장','공급의 변화','경제적 지대','인적자본']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "빵을 만들려면 일할 사람, 오븐 같은 기계, 가게 터가 필요해요.\n이게 각각 노동, 자본, 토지예요."}, {"type": "table", "title": "생산요소와 대가", "columns": ["생산요소", "받는 대가"], "rows": [["노동", "임금"], ["자본", "이자"], ["토지", "지대"]]}, {"type": "text", "title": "왜 중요할까?", "body": "원유, 임금, 이자, 임대료가 오르면 만드는 비용이 커져요.\n그래서 공급곡선이 왼쪽으로 움직여요."}]'::jsonb,ARRAY['tesat']::text[]),
(1011,'수요의 법칙','다른 조건이 같을 때 가격이 오르면 사려는 양이 줄고 내리면 느는 관계','수요의 법칙은 다른 조건이 모두 같다면 가격과 수요량이 반대 방향으로 움직인다는 법칙이다. 그래서 수요곡선은 오른쪽 아래로 내려가는 모양이 된다. 기펜재와 베블런 효과는 이 법칙의 예외로 꼽힌다.','','ㅅㅇㅇㅂㅊ',ARRAY['수요곡선','수요량의 변화','기펜재','베블런효과']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "붕어빵이 비싸지면 덜 사고 싸지면 더 사요.\n소득, 유행처럼 가격 말고 다른 조건은 멈춰두고 본다는 게 전제예요."}, {"type": "table", "title": "가격과 수요량", "columns": ["가격", "사려는 양"], "rows": [["100원", "5개"], ["50원", "10개"]]}, {"type": "text", "title": "왜 중요할까?", "body": "\"다른 조건이 같다면\"이 핵심이에요.\n소득이 늘어 더 사는 건 수요의 법칙이 아니라 수요의 변화예요."}]'::jsonb,ARRAY['tesat']::text[]),
(1012,'수요량의 변화','그 상품 자체의 가격이 바뀌어 수요곡선 위에서 점이 움직이는 것','수요량의 변화는 그 상품 가격이 바뀔 때 특정 가격에서 사려는 양이 바뀌는 것이다. 그래프에서는 수요곡선 자체는 그대로이고 곡선 위의 점만 이동한다. 소득이나 다른 상품 가격이 바뀌는 수요의 변화와 구분해야 한다.','','ㅅㅇㄹㅇㅂㅎ',ARRAY['수요의 변화','수요곡선','수요의 법칙']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "라면값이 1,000원에서 800원으로 내려 더 사면\n같은 곡선 위에서 점만 옮겨간 거예요.\n이게 수요량의 변화예요."}, {"type": "table", "title": "수요량의 변화 vs 수요의 변화", "columns": ["구분", "수요량의 변화", "수요의 변화"], "rows": [["원인", "그 상품의 가격", "소득, 대체재 가격, 인구 등"], ["그래프", "곡선 위 점 이동", "곡선 자체가 좌우 이동"], ["예시", "100원→50원, 5개→10개", "월급이 올라 같은 값에 더 삼"]]}, {"type": "text", "title": "헷갈리기 쉬운 점", "body": "\"가격 상승\"은 수요량 감소예요.\n\"가격 상승 예상\"은 가격 외 요인이라 수요 증가예요."}]'::jsonb,ARRAY['tesat']::text[]),
(1013,'수요의 변화','가격 말고 소득·취향 같은 다른 요인이 바뀌어 수요곡선 전체가 이동하는 것','수요의 변화는 소득, 대체재와 보완재 가격, 기호, 인구, 가격 예상처럼 그 상품 가격 외 요인이 바뀔 때 일어난다. 모든 가격에서 사려는 양이 함께 바뀌어 수요곡선이 통째로 좌우 이동한다. 오른쪽 이동은 수요 증가, 왼쪽 이동은 수요 감소다.','','ㅅㅇㅇㅂㅎ',ARRAY['수요량의 변화','수요곡선','대체재','보완재']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "가격은 그대로인데 월급이 올라 더 사게 되면\n곡선이 통째로 오른쪽으로 옮겨가요.\n이게 수요의 변화예요."}, {"type": "table", "title": "수요곡선을 움직이는 요인", "columns": ["바뀐 것", "수요곡선"], "rows": [["소득 증가(정상재)", "오른쪽"], ["소득 증가(열등재)", "왼쪽"], ["대체재 값 상승", "오른쪽"], ["보완재 값 상승", "왼쪽"], ["가격 상승 예상", "오른쪽"], ["인구 증가", "오른쪽"]]}, {"type": "text", "title": "왜 중요할까?", "body": "수요곡선은 오른쪽 이동과 위쪽 이동이 같은 말이에요.\n수요 증가는 균형가격과 거래량을 둘 다 올려요."}]'::jsonb,ARRAY['tesat']::text[]),
(1014,'수요곡선','가격별로 사려는 양을 이어 그린 오른쪽 아래로 내려가는 선','수요곡선은 세로축에 가격, 가로축에 수요량을 놓고 각 가격에서 사려는 양을 이은 선이다. 수요의 법칙 때문에 오른쪽 아래로 내려가며 D로 표시한다. 곡선의 높이는 그 개수째에 소비자가 내려는 최대 금액, 곧 한계편익을 뜻한다.','','ㅅㅇㄱㅅ',ARRAY['수요의 법칙','공급곡선','수요함수','한계효용']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "\"얼마면 몇 개 살래?\"에 대한 답을 점으로 찍어 이은 선이에요.\n비쌀수록 덜 사니 오른쪽 아래로 내려가요."}, {"type": "line", "title": "수요곡선 예시", "unit": "개", "x": ["500원", "1,000원", "1,500원", "2,000원"], "series": [{"name": "사려는 양", "values": [80, 60, 40, 20]}], "caption": "가격이 오를수록 사려는 양이 줄어요."}, {"type": "text", "title": "왜 중요할까?", "body": "수요곡선이 우하향하는 이유는 한계효용 체감으로 설명돼요.\n하나 더 살수록 만족이 줄어 내려는 금액도 줄어요."}]'::jsonb,ARRAY['tesat']::text[]),
(1015,'유량과 저량','일정 기간 동안 흐른 양과 특정 시점에 쌓여 있는 양을 나누는 구분','유량은 일정 기간 동안 측정한 흐름으로 GDP, 월급, 이자, 수요와 공급이 여기에 속한다. 저량은 특정 시점에 존재하는 양으로 통장 잔고, 외환보유액, 대출 잔액이 대표적이다. 재무제표로 보면 손익계산서는 유량, 재무상태표는 저량이다.','','ㅇㄹㄱㅈㄹ',ARRAY['국내총생산(GDP)','외환보유액','수요의 법칙']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "\"월급 300만원\"은 한 달이라는 기간이 있어야 뜻이 통해서 유량이에요.\n\"통장에 300만원\"은 지금 이 순간의 양이라 저량이에요."}, {"type": "table", "title": "유량 vs 저량", "columns": ["구분", "유량(Flow)", "저량(Stock)"], "rows": [["기준", "일정 기간 동안의 흐름", "특정 시점의 상태"], ["예시", "GDP, 월급, 이자, 월세", "통장 잔고, 외환보유액"], ["재무제표", "손익계산서", "재무상태표"]]}, {"type": "text", "title": "헷갈리기 쉬운 점", "body": "대출 잔액은 저량이고, 한 달 새 늘어난 대출은 유량이에요.\n\"기간\"이 붙으면 유량이라고 기억해요."}]'::jsonb,ARRAY['tesat']::text[]),
(1016,'정상재','소득이 늘면 수요도 늘어나는 보통의 재화','정상재는 소득이 증가할 때 수요가 증가해 수요곡선이 오른쪽으로 이동하는 재화다. 소득탄력성이 0보다 크며, 그중 1보다 크면 사치재, 0과 1 사이면 필수재로 나눈다. 같은 상품도 시대나 소득 수준에 따라 정상재에서 열등재로 바뀔 수 있다.','','ㅈㅅㅈ',ARRAY['열등재','중립재','소득탄력성','사치재']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "월급이 오르면 쇠고기나 자동차를 더 사요.\n이런 재화가 정상재예요."}, {"type": "table", "title": "소득이 늘 때 재화별 반응", "columns": ["구분", "소득이 늘면", "수요곡선", "예시"], "rows": [["정상재", "수요 증가", "오른쪽 이동", "쇠고기, 자동차"], ["열등재", "수요 감소", "왼쪽 이동", "라면, 대중교통"], ["중립재", "변화 없음", "그대로", "-"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1017,'중립재','소득이 늘거나 줄어도 수요가 거의 변하지 않는 재화','중립재는 소득이 변해도 수요가 변하지 않아 수요곡선이 그대로인 재화다. 소득탄력성이 0에 해당한다. 소득에 대한 반응으로 재화를 정상재, 열등재, 중립재로 나눌 때 쓰는 개념이다.','','ㅈㄹㅈ',ARRAY['정상재','열등재','소득탄력성']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "월급이 올라도 내려도 사는 양이 그대로인 물건이에요.\n소득 변화에 꿈쩍 않는다고 보면 돼요."}, {"type": "table", "title": "소득탄력성으로 보는 재화", "columns": ["소득탄력성", "재화"], "rows": [["0보다 작음", "열등재"], ["0", "중립재"], ["0보다 큼", "정상재"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1018,'공급의 법칙','다른 조건이 같을 때 가격이 오르면 팔려는 양이 늘고 내리면 주는 관계','공급의 법칙은 다른 조건이 모두 같다면 가격과 공급량이 같은 방향으로 움직인다는 법칙이다. 비쌀수록 더 만들어 팔려고 하므로 공급곡선은 오른쪽 위로 올라간다. 공급도 일정 기간 동안의 의사라 유량에 속한다.','','ㄱㄱㅇㅂㅊ',ARRAY['공급곡선','공급량의 변화','수요의 법칙']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "붕어빵이 비싸게 팔리면 장사꾼은 더 많이 굽고 싶어 해요.\n싸지면 덜 굽게 돼요."}, {"type": "table", "title": "수요 vs 공급", "columns": ["구분", "수요", "공급"], "rows": [["기호", "D(Demand)", "S(Supply)"], ["가격과의 관계", "반대 방향", "같은 방향"], ["곡선 모양", "우하향", "우상향"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1019,'공급곡선','가격별로 팔려는 양을 이어 그린 오른쪽 위로 올라가는 선','공급곡선은 세로축에 가격, 가로축에 공급량을 놓고 각 가격에서 팔려는 양을 이은 선으로 S로 표시한다. 공급의 법칙 때문에 우상향하며, 곡선의 높이는 그 개수째를 만드는 한계비용을 뜻한다. 공급곡선은 왼쪽 이동과 위쪽 이동이 같은 말이라 위로 움직이면 공급 감소다.','','ㄱㄱㄱㅅ',ARRAY['공급의 법칙','수요곡선','한계비용','생산자잉여']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "\"얼마면 몇 개 팔래?\"에 대한 답을 이은 선이에요.\n비쌀수록 더 팔려고 하니 오른쪽 위로 올라가요."}, {"type": "line", "title": "공급곡선 예시", "unit": "개", "x": ["500원", "1,000원", "1,500원", "2,000원"], "series": [{"name": "팔려는 양", "values": [20, 40, 60, 80]}], "caption": "가격이 오를수록 팔려는 양이 늘어요."}, {"type": "text", "title": "헷갈리기 쉬운 점", "body": "공급곡선이 \"위로\" 이동하면 공급 감소예요.\n같은 양을 팔려면 더 높은 가격을 받아야 하는 상태라서요."}]'::jsonb,ARRAY['tesat']::text[]),
(1020,'공급량의 변화','그 상품 자체의 가격이 바뀌어 공급곡선 위에서 점이 움직이는 것','공급량의 변화는 그 상품 가격이 바뀔 때 특정 가격에서 팔려는 양이 바뀌는 것이다. 공급곡선은 그대로이고 곡선 위의 점만 움직인다. 비용, 기술, 세금처럼 다른 요인이 바뀌는 공급의 변화와 구분해야 한다.','','ㄱㄱㄹㅇㅂㅎ',ARRAY['공급의 변화','공급곡선','수요량의 변화']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "가격이 50원에서 100원으로 올라 5개 팔던 걸 10개 팔면\n같은 곡선 위에서 점만 움직인 공급량의 변화예요."}, {"type": "table", "title": "공급량의 변화 vs 공급의 변화", "columns": ["구분", "공급량의 변화", "공급의 변화"], "rows": [["원인", "그 상품의 가격", "비용, 기술, 세금 등"], ["그래프", "곡선 위 점 이동", "곡선 자체가 좌우 이동"], ["예시", "50원→100원, 5개→10개", "원유값이 올라 같은 값에 덜 팖"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1021,'공급의 변화','생산비·기술·세금 같은 가격 외 요인이 바뀌어 공급곡선 전체가 이동하는 것','공급의 변화는 생산요소 가격, 기술, 세금, 보조금처럼 그 상품 가격 외 요인이 바뀔 때 일어난다. 비용이 오르면 같은 가격에서 덜 팔려고 해 공급곡선이 왼쪽으로, 비용이 내리면 오른쪽으로 이동한다. 공급곡선의 왼쪽 이동은 위쪽 이동과 같은 공급 감소다.','','ㄱㄱㅇㅂㅎ',ARRAY['공급량의 변화','공급곡선','생산요소','비용인상 인플레이션']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "원유값이 오르면 같은 값에 덜 만들려고 해요.\n곡선이 통째로 왼쪽으로 옮겨가는 공급 감소예요."}, {"type": "table", "title": "공급곡선을 움직이는 요인", "columns": ["바뀐 것", "비용", "공급곡선"], "rows": [["원유값·임금·이자·임대료 상승", "증가", "왼쪽 이동"], ["세금 증가", "증가", "왼쪽 이동"], ["기술 발전", "감소", "오른쪽 이동"], ["보조금", "감소", "오른쪽 이동"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1022,'시장수요곡선','같은 가격에서 모든 소비자가 사려는 양을 더해 만든 시장 전체의 곡선','시장수요곡선은 개별 소비자의 수요곡선을 수평으로 합해 만든 시장 전체의 수요곡선이다. 같은 가격에서 각자의 수요량을 더하므로 개별 곡선보다 옆으로 넓어진다. 인구가 늘어 소비자가 많아지면 시장수요곡선은 오른쪽으로 이동한다.','','ㅅㅈㅅㅇㄱㅅ',ARRAY['개별수요곡선','수평합','수요곡선']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "한 사람의 수요를 모두 모으면 시장 전체 수요가 돼요.\n가격은 그대로 두고 사려는 양만 더해요."}, {"type": "table", "title": "A와 B 두 사람의 시장", "columns": ["가격", "A 수요량", "B 수요량", "시장 수요량"], "rows": [["100원", "3개", "5개", "8개"], ["50원", "6개", "10개", "16개"]], "caption": "100원에 8개, 50원에 16개를 이으면 시장수요곡선이에요."}]'::jsonb,ARRAY['tesat']::text[]),
(1023,'개별수요곡선','소비자 한 사람이 가격별로 사려는 양을 나타낸 곡선','개별수요곡선은 한 소비자의 수요함수에서 가격 외 요인을 모두 상수로 묶고 가격과 수요량만 남긴 곡선이다. 예를 들어 q = 2 - p 같은 식이 한 사람의 개별수요곡선이다. 여러 사람의 개별수요곡선을 수평합하면 시장수요곡선이 된다.','','ㄱㅂㅅㅇㄱㅅ',ARRAY['시장수요곡선','수평합','수요함수']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "나 혼자 붕어빵 값에 따라 몇 개 살지를 그린 선이에요.\n시장 전체가 아니라 한 사람 몫이에요."}, {"type": "table", "title": "개별 vs 시장수요곡선", "columns": ["구분", "개별수요곡선", "시장수요곡선"], "rows": [["대상", "소비자 한 명", "모든 소비자"], ["만드는 법", "수요함수에서 가격 외 요인 고정", "개별 곡선을 수평합"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1024,'수평합','같은 가격에서 각 소비자의 수요량을 옆으로 더하는 방법','수평합은 가격(세로축)은 그대로 두고 수량(가로축)만 더해 시장 전체 곡선을 만드는 방법이다. 식이 p = ... 꼴로 주어지면 반드시 q = ... 꼴로 바꾼 뒤 더해야 한다. 같은 소비자가 N명이면 q 식에 N을 곱하고, 서로 다르면 q 식끼리 더한다.','','ㅅㅍㅎ',ARRAY['시장수요곡선','개별수요곡선','수요함수']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "100원일 때 A가 3개, B가 5개를 사면 시장은 8개예요.\n가격끼리가 아니라 수량끼리 더해요."}, {"type": "flow", "title": "수평합 계산 순서", "steps": ["p = 80 - 4q를 q로 정리", "q = 20 - (1/4)p", "같은 사람 8명이면 8을 곱함", "시장 수요량 = 160 - 2p"], "caption": "p 식에 바로 8을 곱하면 가격까지 8배가 돼 틀려요."}, {"type": "text", "title": "헷갈리기 쉬운 점", "body": "qA + qB를 2q로 보고 2로 나누면 안 돼요.\n더한 결과가 그대로 시장 수요량이에요."}]'::jsonb,ARRAY['tesat']::text[]),
(1025,'수요함수','가격·소득·다른 상품 가격 등에 따라 사려는 양이 얼마인지 나타낸 식','수요함수는 수요량에 영향을 주는 가격, 소득, 대체재와 보완재 가격, 기호, 인구 등을 하나의 식으로 나타낸 것이다. 가격 외 요인을 상수로 고정하면 가격과 수요량만 남은 수요곡선이 된다. 소비자 이론에서는 효용 극대화 조건으로 x = M ÷ 2Px 같은 수요함수를 직접 구한다.','','ㅅㅇㅎㅅ',ARRAY['수요곡선','개별수요곡선','수요곡선 도출']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "\"이 값이면 이만큼 산다\"를 식으로 적은 거예요.\n소득 같은 다른 요인은 식의 상수 안에 들어가요."}, {"type": "table", "title": "식과 그래프", "columns": ["식", "가로축 절편", "세로축 절편"], "rows": [["P = -2Q + 4", "2", "4"], ["P = -2Q + 6", "3", "6"]], "caption": "상수가 바뀌면 기울기는 그대로고 선이 평행 이동해요. 이게 수요의 변화예요."}]'::jsonb,ARRAY['tesat']::text[]),
(1026,'시장균형','사려는 양과 팔려는 양이 같아져 가격과 거래량이 더 움직이지 않는 상태','시장균형은 수요곡선과 공급곡선이 만나는 균형점에서 수요량과 공급량이 같아진 상태다. 균형보다 비싸면 초과공급으로 값이 내리고, 싸면 초과수요로 값이 올라 다시 균형으로 돌아온다. 밖에서 충격이 오지 않는 한 이 상태가 유지된다.','','ㅅㅈㄱㅎ',ARRAY['균형가격','균형거래량','초과수요','초과공급']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "경매장에서 사려는 사람이 많으면 값이 오르고 적으면 내려요.\n그러다 사려는 양과 팔려는 양이 같아지는 곳에서 멈춰요."}, {"type": "table", "title": "한 곡선만 움직일 때", "columns": ["변화", "균형가격", "균형거래량"], "rows": [["수요 증가", "상승", "증가"], ["수요 감소", "하락", "감소"], ["공급 증가", "하락", "증가"], ["공급 감소", "상승", "감소"]]}, {"type": "table", "title": "두 곡선이 같이 움직일 때", "columns": ["수요", "공급", "균형거래량", "균형가격"], "rows": [["증가", "증가", "증가", "알 수 없음"], ["감소", "감소", "감소", "알 수 없음"], ["증가", "감소", "알 수 없음", "상승"], ["감소", "증가", "알 수 없음", "하락"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1027,'균형가격','수요량과 공급량이 정확히 같아지는 가격','균형가격은 수요곡선과 공급곡선이 만나는 점의 가격으로 P*로 표시한다. 이 가격에서는 물건이 남지도 모자라지도 않는다. 식이 주어지면 수요식과 공급식을 같다고 놓고 풀어서 구한다.','','ㄱㅎㄱㄱ',ARRAY['시장균형','균형거래량','수요와 공급']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "사려는 사람과 팔려는 사람이 모두 만족해서\n물건이 남지도 모자라지도 않는 값이에요."}, {"type": "flow", "title": "균형가격 계산", "steps": ["수요 q = 40 - p, 공급 q = 2p - 20", "40 - p = 2p - 20으로 놓기", "3p = 60, p = 20", "공급식에 넣어 q = 20 확인"]}, {"type": "table", "title": "수요가 늘어난 뒤", "columns": ["구분", "균형가격", "균형거래량"], "rows": [["처음", "20", "20"], ["수요 q = 55 - p로 증가 후", "25", "30"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1028,'균형거래량','균형가격에서 실제로 사고팔리는 물건의 양','균형거래량은 수요곡선과 공급곡선이 만나는 점의 수량으로 Q*로 표시한다. 수요가 움직이면 균형가격과 같은 방향으로, 공급이 움직이면 반대 방향으로 변한다. 수요와 공급이 반대 방향으로 동시에 움직이면 균형거래량의 방향은 알 수 없다.','','ㄱㅎㄱㄹㄹ',ARRAY['균형가격','시장균형','사중손실']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "균형가격에서 실제로 손바뀜이 일어나는 양이에요.\n가격이 아니라 거래된 개수를 보는 거예요."}, {"type": "text", "title": "외우는 요령", "body": "두 곡선이 같은 방향으로 움직이면 거래량이 확실하고 가격이 불확실해요.\n반대 방향이면 가격이 확실하고 거래량이 불확실해요."}]'::jsonb,ARRAY['tesat']::text[]),
(1029,'초과수요','가격이 균형보다 낮아 사려는 양이 팔려는 양보다 많은 상태','초과수요는 시장가격이 균형가격보다 낮을 때 수요량이 공급량을 넘어서 물건이 모자라는 상태다. 사려는 사람끼리 경쟁하면서 가격이 오르고 균형으로 돌아간다. 최고가격제처럼 가격을 균형 아래로 묶으면 초과수요가 계속 남아 암시장이 생길 수 있다.','','ㅊㄱㅅㅇ',ARRAY['초과공급','시장균형','최고가격제']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "인기 공연 표가 정가가 너무 싸서 금방 동나는 상황이에요.\n모자라니 웃돈을 붙인 암표가 등장해요."}, {"type": "table", "title": "초과수요 vs 초과공급", "columns": ["구분", "초과수요", "초과공급"], "rows": [["가격 위치", "균형보다 쌈", "균형보다 비쌈"], ["상황", "물건이 모자람", "물건이 남음"], ["가격 변화", "상승", "하락"], ["규제 사례", "최고가격제", "최저가격제"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1030,'초과공급','가격이 균형보다 높아 팔려는 양이 사려는 양보다 많은 상태','초과공급은 시장가격이 균형가격보다 높을 때 공급량이 수요량을 넘어서 물건이 남는 상태다. 팔려는 사람이 값을 내리면서 가격이 균형으로 돌아간다. 최저가격제처럼 가격을 균형 위로 묶으면 초과공급이 남고, 노동시장에서는 비자발적 실업으로 나타난다.','','ㅊㄱㄱㄱ',ARRAY['초과수요','시장균형','최저가격제','최저임금제']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "시즌이 끝난 옷이 창고에 쌓이는 상황이에요.\n남은 물건을 팔려고 떨이 할인을 해요."}, {"type": "text", "title": "왜 중요할까?", "body": "최저임금처럼 하한을 시장보다 높게 정하면\n일하려는 사람이 일자리보다 많아지는 초과공급이 생길 수 있어요."}]'::jsonb,ARRAY['tesat']::text[]),
(1031,'탄력적 수요','가격이 조금만 변해도 사려는 양이 그보다 큰 비율로 변하는 수요','탄력적 수요는 수요의 가격탄력성이 1보다 커서 수요량 변화율이 가격 변화율보다 큰 경우다. 대체재가 많거나 지출 비중이 크거나 사치품일수록 탄력적이 된다. 이런 상품은 값을 내려야 총수입이 늘어난다.','','ㅌㄹㅈㅅㅇ',ARRAY['비탄력적 수요','수요탄력성','총수입','대체재']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "과자값이 내리면 훨씬 많이 사고 오르면 안 사버려요.\n가격에 민감하게 반응하는 수요예요."}, {"type": "table", "title": "탄력적 vs 비탄력적", "columns": ["구분", "탄력적", "비탄력적"], "rows": [["탄력성 값", "1 초과", "1 미만"], ["수요량 반응", "가격보다 더 변함", "가격보다 덜 변함"], ["수요곡선(같은 점 비교)", "완만함", "가파름"], ["예시", "과자", "쌀"]]}, {"type": "table", "title": "탄력적이 되는 요인", "columns": ["요인", "탄력적이 되는 쪽"], "rows": [["대체재 수", "많을수록"], ["지출 비중", "클수록"], ["측정 기간", "길수록"], ["상품 범위", "좁을수록"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1032,'비탄력적 수요','가격이 변해도 사려는 양이 그보다 작은 비율로만 변하는 수요','비탄력적 수요는 수요의 가격탄력성이 1보다 작아 수요량 변화율이 가격 변화율보다 작은 경우다. 쌀, 담배, 휘발유처럼 대신할 것이 적은 필수품이 대표적이다. 이런 상품은 값을 올리면 판매량이 덜 줄어 총수입이 늘어난다.','','ㅂㅌㄹㅈㅅㅇ',ARRAY['탄력적 수요','수요탄력성','총수입','풍년의 역설']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "쌀값이 올라도 밥은 먹어야 하니 먹는 양이 크게 안 줄어요.\n가격에 둔하게 반응하는 수요예요."}, {"type": "table", "title": "가격 40% 하락 시", "columns": ["상품", "수요량 변화", "탄력성"], "rows": [["쌀", "20% 증가", "0.5(비탄력적)"], ["과자", "100% 증가", "2.5(탄력적)"]]}, {"type": "text", "title": "헷갈리기 쉬운 점", "body": "쇠고기값이 20% 오르고 수요량이 5% 줄면 탄력성 0.25예요.\n비탄력적이라 값을 올리면 매출이 늘어요."}]'::jsonb,ARRAY['tesat']::text[]),
(1033,'단위탄력적','가격이 변한 비율과 똑같은 비율로 수요량이 변하는 상태','단위탄력적은 수요의 가격탄력성이 정확히 1인 경우를 말한다. 가격이 오른 만큼 판매량이 같은 비율로 줄어 총수입이 변하지 않는다. 직선 수요곡선의 중점과 직각쌍곡선 수요곡선의 모든 점이 단위탄력적이다.','','ㄷㅇㅌㄹㅈ',ARRAY['탄력적 수요','비탄력적 수요','직각쌍곡선','총수입']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "값이 10% 오르면 사려는 양도 정확히 10% 줄어요.\n그래서 매출은 그대로예요."}, {"type": "table", "title": "탄력성 다섯 구간", "columns": ["탄력성 값", "이름", "수요곡선"], "rows": [["0", "완전비탄력적", "수직선"], ["0~1", "비탄력적", "가파름"], ["1", "단위탄력적", "-"], ["1 초과", "탄력적", "완만함"], ["무한대", "완전탄력적", "수평선"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1034,'완전탄력적','가격이 아주 조금만 변해도 수량이 무한히 변하는 극단적인 상태','완전탄력적은 탄력성이 무한대인 경우로, 곡선이 가로축과 평행한 수평선이 된다. 공급이 완전탄력적이면 수요가 늘어도 가격은 그대로고 거래량만 늘어난다. 수요가 완전탄력적이면 공급자에게 매긴 세금을 공급자가 전부 부담한다.','','ㅇㅈㅌㄹㅈ',ARRAY['완전비탄력적','탄력적 수요','조세 귀착']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "정해진 가격에서 원하는 만큼 다 사고팔 수 있는 상태예요.\n값을 조금만 올려도 아무도 안 사요."}, {"type": "table", "title": "수요가 늘 때 공급이 극단이면", "columns": ["공급", "균형가격", "균형거래량"], "rows": [["완전탄력적(수평선)", "그대로", "증가"], ["완전비탄력적(수직선)", "상승", "그대로"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1035,'완전비탄력적','가격이 아무리 변해도 수량이 전혀 변하지 않는 극단적인 상태','완전비탄력적은 탄력성이 0인 경우로, 곡선이 세로축과 평행한 수직선이 된다. 토지나 골동품처럼 양 자체가 고정된 재화의 공급이 대표적이다. 공급이 완전비탄력적이면 수요가 늘 때 거래량은 그대로고 가격만 오르며, 세금은 공급자가 전부 부담한다.','','ㅇㅈㅂㅌㄹㅈ',ARRAY['완전탄력적','비탄력적 수요','공급탄력성','경제적 지대']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "땅은 값이 오른다고 더 만들 수 없어요.\n가격과 상관없이 양이 고정된 상태예요."}, {"type": "text", "title": "왜 중요할까?", "body": "공급이 수직선이면 수요가 늘어도 양은 못 늘고 가격만 올라요.\n도심 땅값이 쉽게 오르는 이유를 이걸로 설명해요."}]'::jsonb,ARRAY['tesat']::text[]),
(1036,'총수입','가격에 판매량을 곱한 기업의 전체 판매 금액','총수입은 가격 × 판매량으로 계산하며 매출액과 같은 뜻이다. 수요가 탄력적이면 값을 내릴 때, 비탄력적이면 값을 올릴 때 총수입이 늘어난다. 직선 수요곡선에서는 탄력성이 1인 중점에서 총수입이 가장 크다.','','ㅊㅅㅇ',ARRAY['탄력적 수요','비탄력적 수요','한계수입','단위탄력적']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "값을 올리면 하나당 받는 돈은 늘지만 덜 팔려요.\n어느 쪽이 더 크게 움직이는지를 탄력성이 정해요."}, {"type": "table", "title": "탄력성과 총수입", "columns": ["탄력성", "가격 인상 시", "가격 인하 시", "유리한 전략"], "rows": [["탄력적(1 초과)", "감소", "증가", "가격 인하"], ["단위탄력적(1)", "변화 없음", "변화 없음", "-"], ["비탄력적(1 미만)", "증가", "감소", "가격 인상"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1037,'풍년의 역설','풍작으로 수확이 늘었는데 값이 폭락해 농가 수입이 오히려 줄어드는 현상','농산물은 먹는 양이 크게 변하지 않아 수요가 비탄력적이다. 그래서 풍년으로 공급이 늘면 판매량은 조금 늘지만 가격이 훨씬 크게 떨어져 농가의 총수입이 줄어든다. 수요와 공급이 모두 비탄력적인 농산물 가격이 크게 출렁이는 이유를 보여준다.','','ㅍㄴㅇㅇㅅ',ARRAY['비탄력적 수요','총수입','절약의 역설','구성의 오류']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "배추 농사가 잘돼 물량이 넘치면 값이 폭락해요.\n많이 수확했는데 손에 쥐는 돈은 줄어드는 거예요."}, {"type": "flow", "title": "풍년의 역설이 생기는 과정", "steps": ["풍작으로 공급 증가", "수요가 비탄력적이라 판매량은 조금만 늘어남", "가격이 크게 하락", "농가 총수입 감소"]}, {"type": "text", "title": "왜 중요할까?", "body": "산지에서 수확한 배추를 갈아엎는 뉴스가 바로 이 현상이에요.\n정부가 수매나 비축으로 가격을 받치는 이유이기도 해요."}]'::jsonb,ARRAY['tesat']::text[]),
(1038,'사치재','소득이 늘어난 비율보다 수요가 더 큰 비율로 늘어나는 재화','사치재는 수요의 소득탄력성이 1보다 큰 정상재다. 소득이 늘면 지출에서 차지하는 비중이 커지며 해외여행, 고급 외식 등이 예로 꼽힌다. 필수재와 사치재를 가르는 기준은 가격탄력성이 아니라 소득탄력성이다.','','ㅅㅊㅈ',ARRAY['필수재','소득탄력성','정상재','베블런효과']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "월급이 10% 오를 때 해외여행 지출이 20% 늘면\n여행은 그 사람에게 사치재예요."}, {"type": "table", "title": "소득탄력성과 재화", "columns": ["소득탄력성", "재화"], "rows": [["1 초과", "사치재(정상재)"], ["0~1", "필수재(정상재)"], ["0 미만", "열등재"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1039,'필수재','소득이 늘어도 수요가 그보다 작은 비율로만 늘어나는 재화','필수재는 수요의 소득탄력성이 0과 1 사이인 정상재다. 쌀, 전기, 기본 식료품처럼 소득과 관계없이 일정량은 꼭 필요한 상품이 해당한다. "필수품은 가격에 비탄력적"이라는 말은 가격 반응이므로, 소득 기준인 필수재 분류와 섞지 않아야 한다.','','ㅍㅅㅈ',ARRAY['사치재','소득탄력성','정상재','엥겔의 법칙']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "월급이 두 배가 돼도 쌀을 두 배로 먹진 않아요.\n소득보다 덜 늘어나는 재화가 필수재예요."}, {"type": "table", "title": "헷갈리기 쉬운 두 기준", "columns": ["구분", "기준", "내용"], "rows": [["필수재·사치재", "소득탄력성", "0~1이면 필수재, 1 초과면 사치재"], ["탄력적·비탄력적", "가격탄력성", "1 초과면 탄력적, 1 미만이면 비탄력적"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1040,'점탄력성','수요곡선 위 한 점에서 잰 가격탄력성','점탄력성은 두 점 사이의 간격을 한없이 줄여 한 점에서 잰 탄력성으로, (1 ÷ 기울기) × (P ÷ Q)로 계산한다. 직선 수요곡선은 기울기가 같아도 P ÷ Q가 점마다 달라 탄력성이 모두 다르다. 중점에서 1이고 위로 갈수록 커지고 아래로 갈수록 작아진다.','','ㅈㅌㄹㅅ',ARRAY['호탄력성','직각쌍곡선','수요탄력성','단위탄력적']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "같은 직선이라도 위쪽은 가격이 높고 수량이 적어서 탄력적이에요.\n아래쪽은 반대라 비탄력적이에요."}, {"type": "table", "title": "P = 100 - Q 위의 점탄력성", "columns": ["점(Q, P)", "점탄력성", "매출(P × Q)"], "rows": [["(0, 100) 윗끝", "무한대", "0"], ["(25, 75)", "3", "1,875"], ["(50, 50) 중점", "1", "2,500"], ["(75, 25)", "1/3", "1,875"], ["(100, 0) 아랫끝", "0", "0"]]}, {"type": "text", "title": "헷갈리기 쉬운 점", "body": "\"직선 수요곡선은 모든 점에서 탄력성이 같다\"는 틀린 말이에요.\n매출은 탄력성이 1인 중점에서 가장 커요."}]'::jsonb,ARRAY['tesat']::text[]),
(1041,'호탄력성','수요곡선 위 두 점 사이의 변화율로 계산한 가격탄력성','호탄력성은 곡선 위 두 점 사이에서 가격과 수요량의 변화율을 비교해 구한 탄력성이다. 시작점 기준으로 계산하면 방향에 따라 값이 달라지므로 두 값의 중간을 기준으로 삼는 중간점 방식을 쓰기도 한다. 두 점 사이를 한없이 줄이면 점탄력성이 된다.','','ㅎㅌㄹㅅ',ARRAY['점탄력성','수요탄력성']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "사과값이 10원에서 20원으로 오를 때 판매량이 얼마나 줄었는지\n두 지점을 비교해 재는 탄력성이에요."}, {"type": "table", "title": "사과 예시: 10원→20원, 1,500개→1,000개", "columns": ["기준", "계산", "탄력성"], "rows": [["시작점", "33.3% ÷ 100%", "1/3"], ["중간점", "(500 ÷ 2,500) ÷ (10 ÷ 30)", "0.6"]], "caption": "같은 문제도 기준에 따라 값이 달라져요."}]'::jsonb,ARRAY['tesat']::text[]),
(1042,'직각쌍곡선','가격과 수량의 곱이 어디서나 같아 모든 점의 탄력성이 1인 곡선','직각쌍곡선은 P × Q가 항상 일정한 곡선으로, 수요곡선이 이 모양이면 모든 점에서 가격탄력성이 1이다. 가격을 내린 만큼 수요량이 같은 비율로 늘어 어느 점에서든 총수입이 같다. 직선 수요곡선이 중점에서만 탄력성 1인 것과 구분된다.','','ㅈㄱㅆㄱㅅ',ARRAY['점탄력성','단위탄력적','총수입']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "가격 100에 10개, 가격 20에 50개라면 매출이 둘 다 1,000이에요.\n어디서든 곱이 같은 곡선이 직각쌍곡선이에요."}, {"type": "table", "title": "직선 vs 직각쌍곡선", "columns": ["구분", "직선 수요곡선", "직각쌍곡선"], "rows": [["탄력성", "점마다 다름(중점만 1)", "모든 점에서 1"], ["매출", "중점에서 최대", "어디서나 같음"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1043,'사회후생','소비자잉여와 생산자잉여를 더해 시장 거래로 사회가 얻는 전체 이득','사회후생은 소비자잉여와 생산자잉여를 합한 값으로 총잉여라고도 한다. 수요와 공급이 만나는 균형 거래량에서 가장 크며, 이보다 많거나 적게 거래하면 줄어든다. 최고가격제나 최저가격제, 세금은 거래량을 줄여 사회후생을 사중손실만큼 감소시킨다.','','ㅅㅎㅎㅅ',ARRAY['소비자잉여','생산자잉여','사중손실','파레토최적']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "사는 쪽이 아낀 돈과 파는 쪽이 더 받은 돈을 합한 거예요.\n시장이 사회에 얼마나 이득을 주는지 재는 잣대예요."}, {"type": "table", "title": "수요 P = 100 - Q, 공급 P = 20 + Q 시장", "columns": ["항목", "규제 전", "상한 40", "하한 80"], "rows": [["거래량", "40", "20", "20"], ["소비자잉여", "800", "1,000", "200"], ["생산자잉여", "800", "200", "1,000"], ["사회후생", "1,600", "1,200", "1,200"]], "caption": "가격을 묶으면 사회후생이 400만큼 사라져요."}, {"type": "text", "title": "왜 중요할까?", "body": "가격규제로 사회후생이 늘어난다는 말은 틀려요.\n균형에서 벗어나면 어느 쪽이든 후생이 줄어요."}]'::jsonb,ARRAY['tesat']::text[]),
(1044,'한계분석','하나 더 했을 때 늘어나는 이득과 비용을 비교해 결정하는 방식','한계는 한 단위를 더 늘릴 때 추가로 생기는 효용, 비용, 수입을 뜻한다. 한계분석은 이 추가분을 비교해 하나 더 했을 때 이득이 비용보다 크면 늘리고 작으면 멈추는 사고방식이다. 전체는 총, 나눠 볼 때는 평균, 결정할 때는 한계를 본다.','','ㅎㄱㅂㅅ',ARRAY['한계효용','한계비용','한계수입','비용편익분석']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "콜라 한 병을 더 마실지 고민할 때\n그 한 병의 만족이 값보다 크면 마시고 작으면 그만둬요."}, {"type": "table", "title": "총·평균·한계", "columns": ["구분", "뜻", "예시"], "rows": [["총", "전체 합", "총비용, 총효용"], ["평균", "전체를 개수로 나눔", "평균비용"], ["한계", "하나 더의 변화", "한계비용, 한계효용"]]}, {"type": "text", "title": "왜 중요할까?", "body": "이미 쓴 돈이 아니라 앞으로 하나 더의 이득과 비용을 봐요.\n기업의 생산량, 소비자의 구매량 결정이 모두 이 방식이에요."}]'::jsonb,ARRAY['tesat']::text[]),
(1045,'평균비용','총비용을 생산량으로 나눈 한 개당 비용','평균비용(AC)은 총비용을 생산량으로 나눈 값으로, 평균고정비용과 평균가변비용의 합이다. 한계비용이 평균비용보다 크면 평균비용이 오르고, 작으면 내려간다. 그래서 한계비용곡선은 평균비용곡선의 가장 낮은 점을 지난다.','','ㅍㄱㅂㅇ',ARRAY['총비용','한계비용','규모의 경제','손익분기점']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "빵 3개를 만드는 데 24원이 들면 한 개당 8원이에요.\n이게 평균비용이에요."}, {"type": "table", "title": "빵 생산 비용", "columns": ["빵", "총비용", "평균비용", "한계비용"], "rows": [["1개", "7원", "7원", "7원"], ["2개", "15원", "7.5원", "8원"], ["3개", "24원", "8원", "9원"]]}, {"type": "text", "title": "평균과 한계의 관계", "body": "새 과목 점수가 평균보다 높으면 평균이 올라요.\nMC가 AC보다 크면 AC가 오르고, 작으면 AC가 내려요."}]'::jsonb,ARRAY['tesat']::text[]),
(1046,'총비용','일정량을 생산하는 데 드는 모든 비용의 합','총비용(TC)은 생산량과 관계없이 드는 고정비용과 생산량에 따라 변하는 가변비용을 더한 것이다. 총비용을 생산량으로 나누면 평균비용, 생산량이 하나 늘 때 늘어난 총비용이 한계비용이다. 예를 들어 TC = 500 + 100Q라면 500은 고정비용, 100Q는 가변비용이다.','','ㅊㅂㅇ',ARRAY['평균비용','한계비용','손익분기점']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "가게 임대료처럼 안 팔아도 나가는 돈과\n재료비처럼 많이 만들수록 늘어나는 돈을 다 더한 거예요."}, {"type": "table", "title": "TC = 500 + 100Q일 때(Q = 10)", "columns": ["구분", "식", "값"], "rows": [["고정비용", "500", "500"], ["가변비용", "100Q", "1,000"], ["평균비용", "500 ÷ Q + 100", "150"], ["한계비용", "100", "100"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1047,'총효용','어떤 재화를 소비해서 얻는 만족을 모두 더한 값','총효용은 소비한 각 단위의 한계효용을 모두 더한 누적 만족이다. 한계효용이 줄어들더라도 0보다 크기만 하면 총효용은 계속 늘어난다. 한계효용이 0이 되는 지점에서 총효용이 가장 크다.','','ㅊㅎㅇ',ARRAY['효용','한계효용','효용 극대화']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "콜라 첫 병, 둘째 병, 셋째 병에서 얻은 만족을 다 더한 게 총효용이에요.\n하나 더의 만족은 줄어도 합계는 천천히 늘어요."}, {"type": "table", "title": "콜라 예시", "columns": ["콜라", "한계효용", "총효용"], "rows": [["1병째", "5,000원어치", "5,000원어치"], ["2병째", "2,000원어치", "7,000원어치"], ["3병째", "400원어치", "7,400원어치"]]}, {"type": "text", "title": "헷갈리기 쉬운 점", "body": "한계효용이 줄면 총효용도 준다는 말은 틀려요.\n한계효용이 0보다 크면 총효용은 계속 늘어요."}]'::jsonb,ARRAY['tesat']::text[]),
(1048,'효용','재화나 서비스를 소비해서 얻는 주관적인 만족','효용은 소비자가 재화나 서비스를 소비하며 느끼는 만족의 크기다. 효용을 돈으로 바꿔 표시한 것을 편익이라 하며, 소비자는 정해진 예산에서 효용을 가장 크게 하려 한다. 같은 상품이라도 사람마다, 상황마다 효용이 다르다.','','ㅎㅇ',ARRAY['총효용','한계효용','효용함수','효용 극대화']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "목마를 때 마시는 시원한 콜라 한 병의 뿌듯함이 효용이에요.\n똑같은 콜라도 배부를 땐 효용이 작아요."}, {"type": "table", "title": "효용과 관련된 말", "columns": ["용어", "뜻"], "rows": [["효용", "소비에서 얻는 만족"], ["편익", "효용을 돈으로 표시한 것"], ["한계효용", "하나 더 소비할 때 늘어나는 만족"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1049,'기회비용 체증','한 재화를 더 만들수록 포기해야 하는 다른 재화의 양이 점점 커지는 현상','기회비용 체증은 한쪽 생산을 늘릴수록 그 재화 한 단위의 기회비용이 커지는 현상이다. 처음에는 그 일에 잘 맞는 자원부터 옮기지만, 나중에는 덜 맞는 자원까지 옮겨야 하기 때문이다. 이 때문에 생산가능곡선은 원점에 대해 오목한 모양이 된다.','','ㄱㅎㅂㅇㅊㅈ',ARRAY['생산가능곡선','기회비용','한계변환율']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "자동차를 더 만들려고 옷 공장 사람을 옮기면\n처음엔 차를 잘 만드는 사람부터, 나중엔 옷을 잘 만드는 사람까지 옮겨야 해요.\n그래서 포기하는 옷이 점점 많아져요."}, {"type": "table", "title": "옷 = 100 - 4 × 자동차^2 예시", "columns": ["자동차", "옷", "1대 더 만들 때 포기하는 옷"], "rows": [["0대", "100벌", "-"], ["1대", "96벌", "4벌"], ["2대", "84벌", "12벌"], ["3대", "64벌", "20벌"], ["4대", "36벌", "28벌"]]}, {"type": "text", "title": "외우는 요령", "body": "생산가능곡선이 우하향하는 건 희소성 때문이에요.\n오목한 건 기회비용 체증 때문이에요."}]'::jsonb,ARRAY['tesat']::text[]),
(1050,'한계변환율','한 재화를 하나 더 만들려고 포기해야 하는 다른 재화의 양','한계변환율(MRT)은 생산가능곡선 위 한 점에서 그은 접선 기울기의 크기와 같다. MRT(X, Y)는 X재를 하나 더 만들 때 포기하는 Y재의 양을 뜻하며, 축 위치가 아니라 첨자 순서로 판단한다. X를 늘릴수록 MRT가 커지는 것이 생산가능곡선이 오목하다는 뜻이다.','','ㅎㄱㅂㅎㅇ',ARRAY['생산가능곡선','기회비용 체증','한계대체율']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "자동차 1대를 더 만들 때 옷을 몇 벌 포기해야 하는지가 한계변환율이에요.\n생산 쪽의 교환 비율이에요."}, {"type": "table", "title": "한계대체율 vs 한계변환율", "columns": ["구분", "한계대체율(MRS)", "한계변환율(MRT)"], "rows": [["누구의 비율", "소비자", "생산자(나라 전체)"], ["곡선", "무차별곡선 기울기", "생산가능곡선 기울기"], ["변화", "X를 늘릴수록 감소", "X를 늘릴수록 증가"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1051,'소비자 균형','정해진 예산 안에서 만족이 가장 커지는 상품 조합을 고른 상태','소비자 균형은 예산 제약 아래에서 효용이 가장 큰 상품 묶음을 선택한 상태다. 그래프로는 예산선과 무차별곡선이 접하는 점이다. 가격이 바뀌면 균형점이 옮겨가는데, 이를 통해 수요곡선이 우하향하는 이유를 설명한다.','','ㅅㅂㅈㄱㅎ',ARRAY['예산선','무차별곡선','소비자 균형 조건','효용 극대화']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "1만원으로 빵과 우유를 살 때\n몇 개씩 사야 가장 뿌듯한지 찾은 상태예요."}, {"type": "table", "title": "예산 1만원, 빵·우유 각 1,000원, U = x × y", "columns": ["빵", "우유", "효용"], "rows": [["1개", "9개", "9"], ["3개", "7개", "21"], ["5개", "5개", "25"], ["7개", "3개", "21"], ["9개", "1개", "9"]], "caption": "골고루 산 5개씩에서 효용이 가장 커요."}, {"type": "text", "title": "헷갈리기 쉬운 점", "body": "예산선과 무차별곡선이 교차하는 점은 균형이 아니에요.\n조합을 바꾸면 더 높은 곡선으로 갈 수 있어요."}]'::jsonb,ARRAY['tesat']::text[]),
(1052,'효용 극대화','주어진 예산으로 소비자가 얻는 만족을 가장 크게 만드는 것','효용 극대화는 소비자 이론에서 가계가 추구한다고 보는 목표다. 기업이 이윤 극대화, 정부가 사회후생 극대화를 추구하는 것과 짝을 이룬다. 효용 극대화를 따르는 소비자를 가정하면 수요곡선이 왜 우하향하는지 설명할 수 있다.','','ㅎㅇㄱㄷㅎ',ARRAY['소비자 균형','효용','경제주체','예산제약']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "같은 돈으로 가장 뿌듯하게 장을 보려는 마음이에요.\n소비자 이론은 사람들이 이렇게 행동한다고 가정해요."}, {"type": "table", "title": "경제주체별 목표", "columns": ["경제주체", "극대화하는 것"], "rows": [["가계", "효용"], ["기업", "이윤"], ["정부", "사회후생"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1053,'효용함수','상품을 얼마나 소비하느냐에 따라 만족이 얼마인지 숫자로 나타낸 식','효용함수는 소비하는 재화의 양과 효용의 관계를 나타낸 식이다. U = x × y처럼 곱하기 꼴이면 골고루 살수록 효용이 커지고, U = x + y처럼 더하기 꼴이면 두 재화를 완전히 바꿔 쓸 수 있다. 정확한 측정보다는 선택의 방향을 설명하는 도구로 쓰인다.','','ㅎㅇㅎㅅ',ARRAY['효용','무차별곡선','한계대체율','소비자 균형']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "빵 몇 개, 우유 몇 개를 넣으면 만족 점수가 나오는 계산기예요."}, {"type": "table", "title": "효용함수 모양", "columns": ["효용함수", "뜻", "예시"], "rows": [["U = x × y", "골고루 살수록 효용이 커짐", "빵과 우유"], ["U = x + y", "하나를 다른 하나로 똑같이 대체", "흑설탕과 백설탕"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1054,'한계대체율','만족을 그대로 두면서 한 재화를 하나 더 얻으려 포기할 수 있는 다른 재화의 양','한계대체율(MRS)은 무차별곡선 위 한 점의 접선 기울기 크기로, MUx ÷ MUy와 같다. 소비자가 주관적으로 기꺼이 바꾸려는 교환 비율이다. 소비자 균형에서는 한계대체율이 시장의 교환 비율인 상대가격과 같아진다.','','ㅎㄱㄷㅊㅇ',ARRAY['무차별곡선','한계대체율 체감','상대가격','한계효용']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "빵 1개를 더 받는 대신 우유를 몇 개까지 내줄 수 있는지예요.\n내 마음속 교환 비율이에요."}, {"type": "table", "title": "상대가격 vs 한계대체율", "columns": ["구분", "상대가격", "한계대체율"], "rows": [["뜻", "시장에서 바꿀 수 있는 비율", "내가 바꾸고 싶은 비율"], ["성격", "객관적, 가격이 정함", "주관적, 선호가 정함"], ["공식", "Px ÷ Py", "MUx ÷ MUy"]]}, {"type": "text", "title": "헷갈리기 쉬운 점", "body": "MRS는 MUy ÷ MUx가 아니라 MUx ÷ MUy예요.\n얻는 재화 X의 한계효용이 분자예요."}]'::jsonb,ARRAY['tesat']::text[]),
(1055,'한계대체율 체감','한 재화를 많이 가질수록 그것을 얻으려 내줄 다른 재화의 양이 줄어드는 현상','한계대체율 체감은 X재를 늘려갈수록 X 한 단위를 위해 포기할 Y재의 양이 점점 줄어드는 현상이다. 흔해진 재화는 덜 아깝고 귀한 재화는 더 아깝기 때문이다. 이 성질 때문에 무차별곡선은 원점에 대해 볼록한 모양이 된다.','','ㅎㄱㄷㅊㅇㅊㄱ',ARRAY['한계대체율','무차별곡선','한계효용']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "과자만 잔뜩 있으면 음료 하나가 아쉬워요.\n과자가 흔해질수록 과자 하나에 내줄 음료가 줄어요."}, {"type": "table", "title": "U = 빵 × 우유 = 12인 곡선", "columns": ["빵", "우유", "빵 1개 더 얻으려 포기하는 우유"], "rows": [["1개", "12개", "-"], ["2개", "6개", "6개"], ["3개", "4개", "2개"], ["4개", "3개", "1개"]], "caption": "포기하는 우유가 6 → 2 → 1로 줄어 곡선이 점점 완만해져요."}]'::jsonb,ARRAY['tesat']::text[]),
(1056,'소비자 선호의 가정','무차별곡선을 그리기 위해 소비자의 좋고 싫음에 대해 두는 기본 전제','대표적인 가정은 완전성, 이행성, 연속성, 단조성, 볼록성 다섯 가지다. 단조성 덕분에 원점에서 먼 무차별곡선일수록 효용이 크고, 볼록성 덕분에 곡선이 원점 쪽으로 휜다. 이 가정이 있어야 무차별곡선이 서로 교차하지 않는다.','','ㅅㅂㅈㅅㅎㅇㄱㅈ',ARRAY['무차별곡선','서수적 효용','한계대체율 체감']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "\"어떤 두 조합이든 비교할 수 있다\", \"많을수록 좋다\"처럼\n소비자에 대해 미리 약속해 두는 규칙이에요."}, {"type": "table", "title": "다섯 가지 가정", "columns": ["가정", "뜻"], "rows": [["완전성", "어떤 두 조합이든 비교할 수 있음"], ["이행성", "A > B, B > C이면 A > C"], ["연속성", "아주 작은 단위로 나눠 소비할 수 있음"], ["단조성", "많을수록 더 좋음"], ["볼록성", "한쪽으로 몰기보다 골고루를 좋아함"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1057,'서수적 효용','만족의 크기가 아니라 어느 쪽이 더 좋은지 순서만 비교하는 효용 개념','서수적 효용은 효용 82와 70이 있을 때 82가 더 좋다는 순서만 의미가 있다고 보는 관점이다. 반대로 기수적 효용은 82가 70보다 정확히 12만큼 더 좋다처럼 크기까지 잴 수 있다고 본다. 무차별곡선 이론은 서수적 효용을 바탕으로 한다.','','ㅅㅅㅈㅎㅇ',ARRAY['효용','무차별곡선','소비자 선호의 가정']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "짜장면이 짬뽕보다 좋다는 건 말할 수 있어도\n정확히 몇 점 더 좋은지는 재기 어려워요.\n순서만 따지는 게 서수적 효용이에요."}, {"type": "table", "title": "서수적 효용 vs 기수적 효용", "columns": ["구분", "서수적 효용", "기수적 효용"], "rows": [["비교하는 것", "순서만", "크기까지"], ["82와 70", "82가 더 좋음", "12만큼 더 좋음"], ["쓰이는 이론", "무차별곡선 이론", "한계효용 이론"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1058,'예산선','가진 돈을 모두 썼을 때 살 수 있는 두 재화의 조합을 이은 선','예산선은 소득 M, X재 가격 Px, Y재 가격 Py일 때 Px × X + Py × Y = M을 만족하는 조합의 선이다. 기울기 크기 Px ÷ Py는 상대가격으로, X 1개를 사려고 포기해야 하는 Y의 양이다. 소득이 바뀌면 평행 이동하고, 한 재화 가격만 바뀌면 회전 이동한다.','','ㅇㅅㅅ',ARRAY['예산제약','상대가격','무차별곡선','소비자 균형']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "내 지갑으로 살 수 있는 한계선이에요.\n선 위는 돈을 다 쓴 조합, 안쪽은 돈이 남는 조합, 바깥은 못 사는 조합이에요."}, {"type": "table", "title": "X재 200원, Y재 100원, 소득 1,000원", "columns": ["구분", "계산", "값"], "rows": [["X절편", "1,000 ÷ 200", "5개"], ["Y절편", "1,000 ÷ 100", "10개"], ["기울기", "-(200 ÷ 100)", "-2"]]}, {"type": "table", "title": "예산선이 움직일 때", "columns": ["변화", "예산선", "기울기"], "rows": [["소득 증가", "바깥으로 평행 이동", "그대로"], ["X재 가격 상승", "X 쪽 끝만 안으로 회전", "가팔라짐"], ["두 가격이 같은 비율로 상승", "안쪽으로 평행 이동", "그대로"]]}]'::jsonb,ARRAY['tesat']::text[]),
(1059,'상대가격','한 재화의 가격을 다른 재화의 양으로 나타낸 교환 비율','상대가격은 Px ÷ Py처럼 두 재화 가격의 비율로, X재 1개를 사려면 Y재를 몇 개 포기해야 하는지를 뜻한다. 예산선 기울기의 크기와 같으며 시장이 정하는 객관적인 교환 비율이다. 모든 가격이 같은 비율로 오르면 상대가격은 변하지 않는다.','','ㅅㄷㄱㄱ',ARRAY['예산선','한계대체율','대체효과','소비자 균형 조건']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "X재가 200원, Y재가 100원이면\nX재 1개는 Y재 2개와 같은 값이에요.\n이 2가 상대가격이에요."}, {"type": "text", "title": "왜 중요할까?", "body": "사람들은 절대 가격보다 상대가격에 반응해요.\n콜라가 비싸지면 사이다가 상대적으로 싸 보여 사이다를 더 사요."}]'::jsonb,ARRAY['tesat']::text[]),
(1060,'예산제약','쓸 수 있는 돈이 정해져 있어 소비 선택이 그 범위 안으로 묶이는 조건','예산제약은 소비자가 가진 소득 이상으로 쓸 수 없다는 조건이다. 기본 모형에서는 저축을 두지 않아 Px × X + Py × Y = M으로 쓴다. 이 조건을 그래프로 나타낸 것이 예산선이며, 소비자는 그 안에서 효용 극대화를 추구한다.','','ㅇㅅㅈㅇ',ARRAY['예산선','효용 극대화','소비자 균형']::text[],'[{"type": "text", "title": "쉽게 설명", "body": "한 달 용돈이 10만원이면 그 안에서만 살 수 있어요.\n갖고 싶은 건 많아도 돈이 한계를 정해요."}, {"type": "table", "title": "예산선 기준 위치", "columns": ["위치", "의미"], "rows": [["예산선 위", "돈을 다 쓴 조합"], ["예산선 안쪽", "살 수 있지만 돈이 남는 조합"], ["예산선 바깥", "돈이 모자라 못 사는 조합"]]}]'::jsonb,ARRAY['tesat']::text[])
